agent_queries.batch:
SELECT 'file=' || current_setting('config_file');
SELECT 'before=' || extract(epoch from clock_timestamp());
SELECT 'signal=' || pg_reload_conf();
SELECT 'waited=' || count(*) FROM (SELECT pg_sleep(1)) AS waited;
SELECT 'loaded=' || extract(epoch from pg_conf_load_time());
SELECT 'error=' || sourceline || ':' || coalesce(name, '') || ':' || error FROM pg_file_settings WHERE error IS NOT NULL AND coalesce(name, '') NOT IN (SELECT name FROM pg_settings WHERE pending_restart) ORDER BY seqno LIMIT 1;

